import {
  isArgparseNegativeNumberToken,
  tryParsePythonInt,
} from '../numbers/pythonInt.mjs';

export const PROGRAM_NAME = 'test14_executable';
export const USAGE_LINE = `usage: ${PROGRAM_NAME} [-h] --a A --b B`;
export const HELP_TEXT = `${USAGE_LINE}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
`;

function buildError(message) {
  return { kind: 'error', message };
}

function parseOptionValue(optionName, rawValue) {
  const parsed = tryParsePythonInt(rawValue);

  if (parsed === null) {
    return buildError(`argument ${optionName}: invalid int value: '${rawValue}'`);
  }

  return { kind: 'value', value: parsed };
}

function isInlineHelpToken(token) {
  return token.startsWith('-h') && token !== '-h' && !token.startsWith('-h=');
}

function isExplicitHelpArgumentToken(token) {
  return token.startsWith('-h=') || token.startsWith('--help=');
}

function getExplicitHelpArgument(token) {
  return token.slice(token.indexOf('=') + 1);
}

function shouldTreatNextTokenAsMissingValue(token) {
  return token.startsWith('-') && !isArgparseNegativeNumberToken(token);
}

export function parseReferenceArgs(argv) {
  for (const token of argv) {
    if (token === '-h' || token === '--help' || isInlineHelpToken(token)) {
      return { kind: 'help' };
    }
  }

  const values = { a: undefined, b: undefined };
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (isExplicitHelpArgumentToken(token)) {
      return buildError(
        `argument -h/--help: ignored explicit argument '${getExplicitHelpArgument(token)}'`,
      );
    }

    if (token === '--a' || token === '--b') {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || shouldTreatNextTokenAsMissingValue(nextToken)) {
        return buildError(`argument ${token}: expected one argument`);
      }

      const parsed = parseOptionValue(token, nextToken);

      if (parsed.kind === 'error') {
        return parsed;
      }

      values[token.slice(2)] = parsed.value;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      const parsed = parseOptionValue('--a', token.slice(4));

      if (parsed.kind === 'error') {
        return parsed;
      }

      values.a = parsed.value;
      continue;
    }

    if (token.startsWith('--b=')) {
      const parsed = parseOptionValue('--b', token.slice(4));

      if (parsed.kind === 'error') {
        return parsed;
      }

      values.b = parsed.value;
      continue;
    }

    unknown.push(token);
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return buildError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (unknown.length > 0) {
    return buildError(`unrecognized arguments: ${unknown.join(' ')}`);
  }

  return { kind: 'ok', values };
}

import { formatPythonInt } from '../numbers/pythonInt.mjs';

function escapePythonBytesCharacter(character) {
  if (character === '\\') {
    return '\\\\';
  }

  if (character === '\'') {
    return '\\\'';
  }

  const code = character.charCodeAt(0);

  if (code >= 32 && code <= 126) {
    return character;
  }

  return `\\x${code.toString(16).padStart(2, '0')}`;
}

export function formatPythonBytesLiteral(value) {
  return `b'${Array.from(value, (character) => escapePythonBytesCharacter(character)).join('')}'`;
}

export function formatPythonValue(value) {
  if (typeof value === 'bigint') {
    return formatPythonInt(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
  }

  throw new TypeError('Unsupported Python display value');
}
